import { createSlice } from "@reduxjs/toolkit";

const initialState = {};

const r_mfpRegisterValue = createSlice({
    name: "r_mfpRegisterValue",
    initialState,
    reducers: {
        setMfpRegisterValue(state, action) {
            state = action.payload;
            return state.name;
        }
    }
});

export const { setMfpRegisterValue } = r_mfpRegisterValue.actions;
export default r_mfpRegisterValue.reducer;