import React, { useEffect } from 'react'
import { useDispatch, useSelector } from "react-redux";
import { useTranslation } from 'react-i18next';
import {
	Form,
	Select,
} from 'antd';

import { DEFAULT_VALUE } from '../content-web-constants.js';
import {
	initializeAll,
	fetchOtherContentJS,
	replacejscssfile,
	chipSeriesToChipType,
} from '../content-web-commonLib.js';

import {
	refresh,
	decideNUC_Pin_Total_Side_Number,
	goToResetValueState,
} from '../libs/pinconfig-libs';

import { setChipType } from "../store/slices/r_chipType";
import { set_partNumber_package } from "../store/slices/r_partNumber_package";
// import { set_partNumber_type } from "../store/slices/r_partNumber_type";
// import { setSnippetName } from "../store/slices/r_snippetName";
// import { set_cfg_perFunctions } from "../store/slices/r_cfg_perFunctions";
import { setMfpRegisterName } from "../store/slices/r_mfpRegisterName";
import { set_module_functions } from "../store/slices/r_module_functions.js";
import { setPinCurrentDescription } from "../store/slices/r_pinCurrentDescription.js";

const { PART_NUMBER } = DEFAULT_VALUE;

const ChipSeries = (props) => {
	const { t } = useTranslation();
	const r_chipType = useSelector((state) => state.r_chipType);
	const dispatch = useDispatch();

	// EXPORT_REACT.setChipType = (value) => dispatch(setChipType(value));
	// EXPORT_REACT.set_partNumber_package = (value) => dispatch(set_partNumber_package(value));
	// EXPORT_REACT.set_partNumber_type = (value) => dispatch(set_partNumber_type(value));
	// EXPORT_REACT.set_cfg_perFunctions = (value) => dispatch(set_cfg_perFunctions(value));
	// EXPORT_REACT.setSnippetName = (value) => dispatch(setSnippetName(value));
	EXPORT_REACT.setMfpRegisterName = (value) => dispatch(setMfpRegisterName(value));
	EXPORT_REACT.setPinCurrentDescription = (value) => dispatch(setPinCurrentDescription(value));

	// From buildChipTypeSelect()
	const handleChangeChipSeries = async (value) => {
		let partNo = PART_NUMBER[value];
		var newPackage = partNo ? partNo.package : "";
		var newType = partNo? partNo.type : "";
		var oldfilename = 'NUC_' + chipSeriesToChipType(r_chipType) + '_Content.js';
		var newfilename = 'NUC_' + chipSeriesToChipType(value) + '_Content.js';

		// await fetchOtherContentJS(chipSeriesToChipType(value));
		replacejscssfile(oldfilename, newfilename, 'js', function(){
			const newPartNumber = NUTOOL_PIN.g_cfg_chips[0].name + "(" + NUTOOL_PIN.g_cfg_chips[0].pkg + ")";
			initializeAll();
			g_partNumber_package = newPartNumber;
			NUTOOL_PIN.decidepackageNumber();
			decideNUC_Pin_Total_Side_Number();
			dispatch(setChipType(value));
			dispatch(set_partNumber_package(newPartNumber));
			// dispatch(set_partNumber_type(newType));
			// dispatch(set_cfg_perFunctions([]));
			// dispatch(setSnippetName(''));
			refresh();
			goToResetValueState();
			dispatch(setMfpRegisterName(Object.assign([], g_gpio_MFPs)));
			dispatch(set_module_functions(Object.assign([], g_module_functions)));
			dispatch(setPinCurrentDescription(
				Object.assign([],
					NUTOOL_PIN.g_cfg_pkgs[NUTOOL_PIN.g_packageNumberIndex].map(() => "")
				)
			));
		});
	}
	const g_cfg_chipSeriesDeveloping = ["M33BU", "M466", "MA35D2", "N9H30xxxIIM", "I94", "N574"];

	const g_cfg_chipSeriesReleased = [
		"CM1003", "CM2003", "CM2052", "CM2U51", "CM3031",
		"ISD9100", "ISD9300",
		"KM1M0DF", "KM1M0GF", "KM1M4BF",
		"KM1M7AF", "KM1M7BF", "KM1M7CF","KM1M7CF4/5",
		"M029G", "M030G", "M031", "M051", "M0518",
		"M0519", "M0564", "M071", "M091", "M0A21",
		"M2003", "M2351", "M2354", "M251", "M261", 
		"M2A23", "M2L31", "M2U51",
		"M3331", "M3351",
		"M433", "M451", "M460", "M471", "M479", "M480",
		"M5531", "M55M1",
		"MA35D0", "MA35D1", "MA35H0",
		"MG51", "MINI51", "ML51", "MS51", "MUG51",
		"N76E003", "N76S003", "N9H30", "N9H31",
		"NANO100", "NDA102", "NM1120", "NM1200", "NM1500",
		"NSC128",
		"NUC029", "NUC100", "NUC200", "NUC400", "NUC505",
		"NUC970", "NUC980", "NUC990",
		"NUC1264"
	];

	const g_cfg_chipSeries = [...new Set(g_bDevelopingTool === true
		? [...g_cfg_chipSeriesReleased, ...g_cfg_chipSeriesDeveloping]
		: [...g_cfg_chipSeriesReleased]
	)].sort((a, b) => a.localeCompare(b));

	// Trigger on initial render
	useEffect(() => {
		handleChangeChipSeries(r_chipType);
	}, []);
	

	return (
		<Form layout="vertical">
			<Form.Item label={<b>{t("LBL_CHIP_SERIES")}</b>}>
				<Select
					value={r_chipType}
					onChange={handleChangeChipSeries}
				>
					{g_cfg_chipSeries.map((chipSeries) =>
						<Select.Option key={chipSeries} value={chipSeries}>
							{chipSeries}
						</Select.Option>)
					}
				</Select>
			</Form.Item>
		</Form>
	);
};

export default ChipSeries;