import { Tooltip } from 'antd';

import {
    isExtension,
    isElectron,
    getPropertyNames,
    checkNodesByMFPregister,
} from './pinconfig-libs';

export {
    setIPCListener,
    setWorkerListener,
    setExtensionListener,
    connectToChipWeb,
    parsingPartNumID,
};

// IPC Renderer
// 趕時間，所以直接複製webusb的flow過來，有機會再合併
function setIPCListener() {
    window.electronAPI.onConnected((event, value) => {
        console.log('electronAPI: onConnected');
        // 確認連接後取PIDValue
        deviceConnected = true;
        window.electronAPI.send('getPIDValue');
    });
    window.electronAPI.onReturnPIDValue((event, pidValue) => {
        console.log('electronAPI: onReturnPIDValue');
        // 取得PIDValue後換成PID
        connectedDevicePID = getPIDFromPIDValue(pidValue);
        console.log('connected device: ' + connectedDevicePID);
        // 確認連接的chip是否為現在畫面上呈現的chip
        const new_partnumber_package = getPartNumber_Package(connectedDevicePID);
        if (new_partnumber_package !== "") {
            EXPORT_REACT.handleChangePartNo(new_partnumber_package);
            setTimeout(() => {
                // 紀錄各個register的預設位址
                var addrs = [];
                var regNames = [];
                regNames = getPropertyNames(NUTOOL_PIN.g_cfg_regDescriptions);
                for (let i = 0; i < regNames.length; i++) {
                    addrs.push(NUTOOL_PIN.g_cfg_regDescriptions[regNames[i]]);
                }
                // 將預設位址送到worker讀值
                window.electronAPI.send('getMFPValues', addrs);
            }, 1000); // 等待MCU change事件處理完畢
        } else {
            // 流程結束，斷開連結
            window.electronAPI.send('connectComplete');
            // 提示使用者選擇正確的型號
            EXPORT_REACT.warning(
                EXPORT_REACT.BTN_CONNECT_TO_TARGET_CHIP,
                EXPORT_REACT.TEXT_CONNECT_TO_TARGET_CHIP_ERR
            );
        }
    });
    // 接收到斷線通知
    window.electronAPI.onReturnRegisterValue((event, result, type) => {
        console.log('electronAPI: onReturnRegisterValue');
        onReturnRegisterValue(result, type);
    });
    // 接收到斷線通知
    window.electronAPI.onDisconnect((event, value) => {
        console.log("electronAPI: onDisconnect");
        deviceConnected = false;
    });
    // 接收到警告訊息
    window.electronAPI.onWarning((event, value) => {
        console.warn(value);
    });
    // NuCAD無法正確執行
    window.electronAPI.onRunNuCADError((event, value) => {
        executeNuCADfail();
    });
};

function setWorkerListener() {
    worker.onmessage = async function (e) {
        let action = e.data.action;
        let data = e.data;
        if (action == 'connected') {
            console.log('worker: connected');
            // 確認連接後取PIDValue
            deviceConnected = true;
            worker.postMessage({ 'action': 'getPIDValue' });
        } else if (action == 'returnPIDValue') {
            console.log('worker: returnPIDValue');
            // 取得PIDValue後換成PID
            connectedDevicePID = getPIDFromPIDValue(data.value);
            console.log('connected device: ' + connectedDevicePID);
            // 確認連接的chip是否為現在畫面上呈現的chip
            const new_partnumber_package = getPartNumber_Package(connectedDevicePID);
            if (new_partnumber_package !== "") {
                EXPORT_REACT.handleChangePartNo(new_partnumber_package);
                setTimeout(() => {
                    // 紀錄各個register的預設位址
                    var addrs = [];
                    var regNames = [];
                    regNames = getPropertyNames(NUTOOL_PIN.g_cfg_regDescriptions);
                    for (let i = 0; i < regNames.length; i++) {
                        addrs.push(NUTOOL_PIN.g_cfg_regDescriptions[regNames[i]]);
                    }
                    // 將預設位址送到worker讀值
                    worker.postMessage({ 'action': 'getMFPValues', 'data': addrs });
                }, 1000);
            } else {
                // 流程結束，斷開連結
                worker.postMessage({ 'action': 'connectComplete' });
                // 提示使用者選擇正確的型號
                EXPORT_REACT.warning(
                    EXPORT_REACT.BTN_CONNECT_TO_TARGET_CHIP,
                    EXPORT_REACT.TEXT_CONNECT_TO_TARGET_CHIP_ERR
                );
            }
        } else if (action == 'returnRegisterValue') {
            console.log('worker: returnRegisterValue');
            onReturnRegisterValue(data.result, data.type);
        } else if (action == 'disconnect') {
            console.log('worker: disconnect');
            deviceConnected = false;
        }
    };
};

function setExtensionListener() {
    window.addEventListener('message', (e) => {
        // Object containing type prop and value prop
        let action = e.data.action;
        let data = e.data.data;

        switch (action) {
            case 'connected':
                console.log('extension: connected');
                // 確認連接後取PIDValue
                deviceConnected = true;
                window.vscode.postMessage({ 'action': 'getPIDValue' });
                break;
            case 'returnPIDValue':
                console.log('extension: returnPIDValue');
                // 取得PIDValue後換成PID
                connectedDevicePID = getPIDFromPIDValue(data);
                // 確認連接的chip是否為現在畫面上呈現的chip
                const new_partnumber_package = getPartNumber_Package(connectedDevicePID);
                if (new_partnumber_package !== "") {
                    EXPORT_REACT.handleChangePartNo(new_partnumber_package);
                    setTimeout(() => {
                        // 紀錄各個register的預設位址
                        var addrs = [];
                        var regNames = [];
                        regNames = getPropertyNames(NUTOOL_PIN.g_cfg_regDescriptions);
                        for (let i = 0; i < regNames.length; i++) {
                            addrs.push(NUTOOL_PIN.g_cfg_regDescriptions[regNames[i]]);
                        }
                        // 將預設位址送到worker讀值
                        window.vscode.postMessage({ 'action': 'getMFPValues', 'data': addrs });
                    }, 1000);
                } else {
                    // 提示使用者選擇正確的型號
                    EXPORT_REACT.warning(
                        EXPORT_REACT.BTN_CONNECT_TO_TARGET_CHIP,
                        EXPORT_REACT.TEXT_CONNECT_TO_TARGET_CHIP_ERR
                    );
                }
                break;
            case 'returnRegisterValue':
                console.log('extension: returnRegisterValue');
                onReturnRegisterValue(data.result, data.type, getPartNumber_Package(connectedDevicePID));
                break;
            case 'disconnect':
                console.log('extension: disconnect');
                deviceConnected = false;
                break;
            default:
                console.warn(action + " is not supported");
                break;
        }
    });
};

async function connectToChipWeb(isUserGesture = false, selectedDevice = undefined) {
    var connDevice = selectedDevice;
    if (worker != undefined) {
        // 由使用者點擊觸發時，若尚未選到裝置，才在這裡呼叫 requestDevice()。
        if (isUserGesture && connDevice == undefined) {
            connDevice = await navigator.usb.requestDevice({
                filters: [{ vendorId: 0x0416 }]
            }).catch(error => {
                console.log(error);
                connDevice = undefined;
            });
        }

        // 非 user gesture 流程，或使用者取消 chooser 時，改查詢既有授權裝置。
        if (connDevice == undefined) {
            await navigator.usb.getDevices().then((devices) => {
                devices.forEach((device) => {
                    connDevice = device;
                });
            }).catch(error => {
                console.log(error);
                connDevice = undefined;
            });
        }
        // 選到任一裝置後，叫worker進行讀PID的動作
        if (connDevice != undefined) {
            worker.postMessage({ 'action': 'connect' });
        }
    }
};

async function parsingPartNumID() {
    const response = await fetch('./PartNumID.cpp');
    const PartNumID = await response.text();
    PartNumID.split(/\r\n|\n/).filter(function (line) {
        var reg = new RegExp('.*[^\/]\{.*0x.*[PROJ].*\}');
        return reg.test(line);
    }).forEach(function (line) { // 根據PartNumID的格式放在PIDPair後存入PIDList
        if (line.indexOf('not release') == -1) {
            // TODO: 有點硬拆，需要轉換成json再來parse
            let pid = line.substring(line.indexOf('"') + 1, line.lastIndexOf('"'));
            let regValue = line.substring(line.indexOf('0x'), line.lastIndexOf('PROJ') - 2);
            let projName = line.substring(line.indexOf('PROJ'), line.lastIndexOf('}'));
            completePIDList.push(pid + '-' + regValue + '-' + projName);
        }
    });
}

function getPIDFromPIDValue(PIDValue) {
    var PIDLine = completePIDList.filter(line => {
        return line.indexOf(PIDValue) != -1;
    });
    if (PIDLine.length === 0) {
        console.warn('getPIDFromPIDValue: no matching PID for value ' + PIDValue);
        return "";
    }
    return PIDLine[0].slicePriorToX('-');
};

function getPartNumber_Package(connectedDevicePID) {
    // check if the connected device is the part number of current chip series
    for (let i = 0, max = NUTOOL_PIN.g_cfg_chips.length; i < max; i += 1) {
        try {
            if (NUTOOL_PIN.g_cfg_chips[i].name.toUpperCase().trim() == connectedDevicePID.toUpperCase().trim()) {
                return NUTOOL_PIN.g_cfg_chips[i].name + '(' + NUTOOL_PIN.g_cfg_chips[i].pkg + ')';
            }
        } catch (err) { }
    }
    // if new device is not found in current chip series, return empty string
    return "";
};

function onReturnRegisterValue(result, type) {
    var regNames = getPropertyNames(NUTOOL_PIN.g_cfg_regDescriptions);
    if (type == 'CortexM') {
        for (var m in result) {
            for (var n = 0; n < regNames.length; n++) {
                if (NUTOOL_PIN.g_cfg_regDescriptions[regNames[n]] == Object.keys(result[m])[0]) {
                    var value = result[m][Object.keys(result[m])[0]];
                    checkNodesByMFPregister(`${regNames[n]}:0x${value.toUpperCase()}`);
                    break;
                }
            }
        }
    } else if (type == '8051') {
        checkNodesByMFPregister(`${data.register}:0x${result.toUpperCase()}`);
    } else {
        console.log("returnRegisterValue: unknown type.");
    }
};

function executeNuCADfail() {
    let toolName = 'NuCAD';

    if (typeof NUTOOL_PIN?.g_anotherNameForNuCAD !== 'undefined' && NUTOOL_PIN.g_anotherNameForNuCAD !== '') {
        toolName = NUTOOL_PIN.g_anotherNameForNuCAD;
    }

    const messageSC = `您的电脑不能执行${toolName}因为它不在Content资料夹里面。`;
    const messageTC = `您的電腦不能執行${toolName}因為它不在Content資料夾裡面。`;
    const messageEN = `Your PC is incapable of executing ${toolName} because it does not exist in the Content folder.`;

    if (typeof showAlertDialog === 'function') {
        showAlertDialog(messageSC, messageTC, messageEN);
        return;
    }

    if (typeof EXPORT_REACT?.warning === 'function') {
        EXPORT_REACT.warning(toolName, messageEN);
        return;
    }

    window.alert(messageEN);
}

