/* global NUTOOL_PINVIEW */
import React, { useRef, useState, useCallback, useEffect } from 'react'
import { useDispatch, useSelector } from "react-redux";
// import { Button, Form, Radio, Space } from 'antd';

import '../App.css';
import { setPkg } from "../store/slices/r_pkg";
import { setAllStatus } from "../store/slices/r_allStatus";
import { setLogs } from "../store/slices/r_settings";

import { renderSVG as renderBGA25 } from '../images/BGA25';
import { renderSVG as renderBGA49 } from '../images/BGA49';
import { renderSVG as renderBGA100 } from '../images/BGA100';
import { renderSVG as renderBGA324 } from '../images/BGA324';
import { renderSVG as renderBGA364 } from '../images/BGA364';
import { renderSVG as renderQFN20 } from '../images/QFN20';
import { renderSVG as renderQFN24 } from '../images/QFN24';
import { renderSVG as renderQFN33 } from '../images/QFN33';
import { renderSVG as renderQFN44 } from '../images/QFN44';
import { renderSVG as renderQFN48 } from '../images/QFN48';
import { renderSVG as renderQFN48_2 } from '../images/QFN48_2';
import { renderSVG as renderQFN64 } from '../images/QFN64';
import { renderSVG as renderQFN80 } from '../images/QFN80';
import { renderSVG as renderQFN88 } from '../images/QFN88';
import { renderSVG as renderQFN100 } from '../images/QFN100';
import { renderSVG as renderQFN128 } from '../images/QFN128';
import { renderSVG as renderQFN144 } from '../images/QFN144';
import { renderSVG as renderQFN176 } from '../images/QFN176';
import { renderSVG as renderQFN216 } from '../images/QFN216';
import { renderSVG as renderSOP10 } from '../images/SOP10';
import { renderSVG as renderSOP14 } from '../images/SOP14';
import { renderSVG as renderSOP20 } from '../images/SOP20';
import { renderSVG as renderSOP28 } from '../images/SOP28';

const svgModuleMap = {
    BGA25: renderBGA25,
    BGA49: renderBGA49,
    BGA100: renderBGA100,
    BGA324: renderBGA324,
    BGA364: renderBGA364,
    QFN20: renderQFN20,
    QFN24: renderQFN24,
    QFN33: renderQFN33,
    QFN44: renderQFN44,
    QFN48: renderQFN48,
    QFN48_2: renderQFN48_2,
    QFN64: renderQFN64,
    QFN80: renderQFN80,
    QFN88: renderQFN88,
    QFN100: renderQFN100,
    QFN128: renderQFN128,
    QFN144: renderQFN144,
    QFN176: renderQFN176,
    QFN216: renderQFN216,
    SOP10: renderSOP10,
    SOP14: renderSOP14,
    SOP20: renderSOP20,
    SOP28: renderSOP28,
};

const supportedSVG = [
    "BGA25",
    "BGA49",
    "BGA100",
    "BGA324",
    "BGA364",
    "QFN20",
    "QFN24",
    "QFN33",
    "QFN44",
    "QFN48",
    "QFN48_2",
    "QFN64",
    "QFN80",
    "QFN88",
    "QFN100",
    "QFN128",
    "QFN144",
    "QFN176",
    "QFN216",
    "SOP10",
    "SOP14",
    "SOP20",
    "SOP28",
];

const getImageType = ((partNo) => {
    // 取最外層括號內容，避免 'I94_48_6X6(QFN48 (6X6))' 這種巢狀括號被截斷
    const start = partNo.indexOf("(");
    const end = partNo.lastIndexOf(")");
    let r_pkg = (start !== -1 && end > start) ? partNo.slice(start + 1, end) : partNo.toString();
    // 去掉封裝尺寸等附註，例如 'QFN48 (6X6)' -> 'QFN48'
    r_pkg = r_pkg.replace(/\s*\(.*$/, "").trim();
    if (r_pkg.includes("_")) {
        console.warn(`Package: ${r_pkg} -> ${r_pkg.split("_")[0]}`);
        r_pkg = r_pkg.split("_")[0];
    }
    switch (r_pkg) {
        // QFN series
        case "LQFP32":
        case "QFN32":
        case "TQFP32":
            return "QFN33";
        case "LQFP44":
            return "QFN44";
        case "LQFP48":
        case "QFN48":
        case "TQFP48":
            if (NUTOOL_PIN.g_packageNumberIndex.includes("(PIN:D10R14U10L14)")) {
                return "QFN48_2";
            }
            else {
                return "QFN48";
            }
        case "HSULQFP64":
        case "LQFP64":
        case "TQFP64":
            return "QFN64";
        case "LQFP80":
        case "TQFP80":
            return "QFN80";
        case "LQFP88":
            return "QFN88";
        case "HQFP100":
        case "LQFP100":
            return "QFN100";
        case "HSULQFP128":
        case "LQFP128":
            return "QFN128";
        case "HQFP144":
        case "LQFP144":
            return "QFN144";
        case "HSULQFP176":
        case "LQFP176":
            return "QFN176";
        case "LQFP216":
            return "QFN216";
        //
        case "MSOP10":
            return "SOP10";
        // TSSOP series
        case "TSSOP14":
            return "SOP14";
        case "SSOP20":
        case "TSSOP20":
            return "SOP20";
        case "TSSOP28":
            return "SOP28";
        // BGA series
        case "WLCSP25":
            return "BGA25";
        case "WLCSP49":
            return "BGA49";
        case "WLCSP100":
            return "BGA100";
        case "BGA312":
            return "BGA324";
        case "BGA364":
            return "BGA364";
        
        default:
            return r_pkg;
    }
});
var dispatch;

const NUTOOL_PINVIEW = {
    isBusy: false,
    _DEBUG: (data) => {
        console.log(data);
    },
};

const PinConfigView = () => {
    // NUTOOL_PINVIEW._DEBUG("PinView()");
    const dispatch = useDispatch();
    const r_settings_hideAllPin = useSelector((state) => state.r_settings_hideAllPin);
    const r_partNumber_package = useSelector((state) => state.r_partNumber_package);
    const r_pinCurrentDescription = useSelector((state) => state.r_pinCurrentDescription);
    const r_pkg = useSelector((state) => state.r_pkg);
    const r_allStatus = useSelector((state) => state.r_allStatus);
    const [renderSVG, setRenderSVG] = useState(null);

    // 拖曳 & 放大 & 縮小
    const [scale, setScale] = useState(1);
    const [position, setPosition] = useState({ x: 0, y: 0 });
    const [svgKey, setSvgKey] = useState(0);
    const draggingRef = useRef(false);
    const hasDraggedRef = useRef(false);
    const startDragRef = useRef({ x: 0, y: 0 });
    let data = {};
    

    const handleWheel = useCallback((event) => {
        if (event.ctrlKey) {
            if (!window.get_status_is_busy){
                window.get_status_is_busy = true;
                setTimeout(()=> {
                    window.get_status_is_busy = false;
                }, 1000);
            }
            //event.preventDefault();
            const scaleAmount = event.deltaY > 0 ? 0.9 : 1.1;
            setScale(prevScale => Math.max(0.1, prevScale * scaleAmount));
        }
    }, []);

    const handleMouseDown = useCallback((event) => {
        NUTOOL_PINVIEW._DEBUG("handleMouseDown()");
        window.get_status_is_busy = true
        draggingRef.current = true;
        hasDraggedRef.current = false;
        startDragRef.current = { x: event.clientX - position.x, y: event.clientY - position.y };
    }, [position]);

    const handleMouseMove = useCallback((event) => {
        if (draggingRef.current) {
            NUTOOL_PINVIEW._DEBUG("handleMouseMove()");
            window.get_status_is_busy = true
            hasDraggedRef.current = true;
            setPosition({
                x: event.clientX - startDragRef.current.x,
                y: event.clientY - startDragRef.current.y
            });
        }
    }, []);

    const handleMouseUp = useCallback(() => {
        NUTOOL_PINVIEW._DEBUG("handleMouseUp()");
        window.get_status_is_busy = false;
        if (draggingRef.current) {
            draggingRef.current = false;
            if (hasDraggedRef.current) {
                setSvgKey(k => k + 1);
            }
        }
    }, []);

    const sharedProps = {
        onWheel: handleWheel,
        onMouseDown: handleMouseDown,
        onMouseMove: handleMouseMove,
        onMouseUp: handleMouseUp,
        onMouseLeave: handleMouseUp,
        style: {
            transform: `scale(${scale}) translate(${position.x}px, ${position.y}px)`,
            cursor: draggingRef.current ? 'grabbing' : 'grab',
            '--pin-focus-color': window.g_colorForFocusedByMouse || undefined
        }
    };

    useEffect(() => {
        const loadJS = async (imageType) => {
            try {
                const renderSVGModule = svgModuleMap[imageType];
                if (!renderSVGModule) {
                    throw new Error(`SVG module not found for package ${imageType}`);
                }
                console.log(`Successfully loaded module for package ${imageType}`);
                setRenderSVG(() => renderSVGModule);
            } catch (error) {
                console.error(`Failed to load module for package ${imageType}:`, error);
            }
        };
        const imageType = getImageType(r_partNumber_package);
        setRenderSVG(() => null);
        if (supportedSVG.includes(imageType)) {
            loadJS(imageType)
        }
        else if (imageType !== ""){
            console.warn(`Unsupported package: ${ imageType }`);
        }
    }, [r_partNumber_package]); // 空数组作为依赖项，确保只在组件挂载和卸载时运行

    useEffect(() => {
        window.addEventListener('message', (e) => {
            // Object containing type prop and value prop
            const msg = e;
            const value = msg.data.value

            switch (msg.data.type) {
                case 'pinview_log':
                    dispatch(setLogs(value));
                    break;
                case 'get_status_success':
                    window.get_status_is_busy = false;
                    dispatch(setPkg(value))
                    dispatch(setAllStatus(value))
                    break;
            }
        });
    }, []);

    try {
        if (renderSVG) {
            data = {
                name:r_partNumber_package,
                name_color: "#000",
                processor: { information: ""},
                pins: NUTOOL_PIN.g_cfg_pkgs[NUTOOL_PIN.g_packageNumberIndex],
                PinDescriptions: g_chipPinDescriptions,
                pinCurrentDescription: r_pinCurrentDescription,
            }
        }

        return (
            <div id="NUC_PinConfiguration_SVG" {...sharedProps}>
                {/* key 帶入封裝名稱，換封裝時強制重建整棵 SVG，避免節點被重用而殘留舊樣式 */}
                <div key={`${r_partNumber_package}-${svgKey}`}>
                    {renderSVG ? (
                        renderSVG(data, r_settings_hideAllPin)
                    ) : (
                            <h1 style={{ textAlign: "center", paddingTop: "30%" }}>
                                {(() => {
                                    if (r_pkg === "") return "Detecting target device ...";
                                    if (r_pkg === "UNSUPPORTED") return "Unsupported device.";
                                    return r_allStatus?.infomation || `Unsupported device. "${r_partNumber_package}"`;
                                })()}
                            </h1>
                    )}
                </div>
            </div>
        );
    } catch (error) {
        console.error(error);
        return <div {...sharedProps}><h1 style={{ textAlign: "center", paddingTop: "30%" }}>Error renderSVG()</h1></div>;
    };
    
};

export default PinConfigView;