import { createSlice } from "@reduxjs/toolkit";
import {
    updateg_pinCurrentModule,
} from "../../libs/pinconfig-libs";

const initialState = [];

const r_pinCurrentDescription = createSlice({
    name: "r_pinCurrentDescription",
    initialState,
    reducers: {
        setPinCurrentDescription(state, action) {
            state = action.payload;
            g_pinCurrentDescription = state;
            updateg_pinCurrentModule(state);
            return state;
        }
    }
});

export const { setPinCurrentDescription } = r_pinCurrentDescription.actions;
export default r_pinCurrentDescription.reducer;