import { Tooltip } from 'antd';

import {
    isGPIOPin,
    isWPPin,
    isCCDBPin,
    isToolTipPin,
    getToolTipPinComment,
} from './pinconfig-libs';

export {
    convertColorHex,
    convertHtmlStr,
    sharedTooltipProps,
    getPinStatus,
    getPinDirection,
    getPinFunctions,
    genBottomPinCmp,
    genBottomPinCmpV2,
    genTopPinCmp,
    genTopPinCmpV2,
    genRightPinCmp,
    genLeftPinCmp,
    genBGABottomIndex,
    genBGALeftIndex,
    genBGACmp,
    genBGACmpV2,
    /////
    genRightPinCmpV2,
    genLeftPinCmpV2,
    onPinClick,
};

function convertColorHex(decVal) {
    return "#fff"
    // return "#" + (decVal >>> 0).toString(16).slice(-6).padStart(6, '0');
};

function convertHtmlStr(string) {
    return (<span dangerouslySetInnerHTML={{ __html: string }}/>);
};

function sharedTooltipProps(string) {
    if(string === "") {
        return {
            title: "",
        }
    }
    else {
        return {
            color: '#ffffe1',
            overlayInnerStyle: {
                color: 'black',
            },
            title: convertHtmlStr(string),
        };
    }
};

function getPinStatus(pin) {
    switch (pin.status) {
        case 65:
            return (<tspan style={{ fill: "red", fontWeight: "bold" }}>H</tspan>);
        case 66:
            return (<tspan style={{ fill: "black", fontWeight: "bold" }}>L&#x00A0;</tspan>);
        default:
            return (<tspan style={{ fontWeight: "bold" }}>&#x00A0;&#x00A0;&#x00A0;</tspan>);
    }
};

function getPinDirection(pin, placement) {
    var bLow = (placement === "bottom" || placement === "right");
    switch (pin.direction) {
        case 4:
            return (<tspan style={{fill: "blue", fontWeight: "bold"}}>&#x27F7;</tspan>);
        // In
        case 1:
            return <tspan style={{ fill: "blue", fontWeight: "bold" }}>{bLow ? "\u27F5" : "\u27F6"}</tspan>;
        // Out
        case 2:
            return <tspan style={{ fill: "blue", fontWeight: "bold" }}>{bLow ? "\u27F6" : "\u27F5"}</tspan>;
        // OpenDrainOut
        case 3: //22B8 27DC 10A9A x16D9 291E
            if (bLow) {
                return <tspan style={{ fill: "blue", fontWeight: "bold" }}>&#x00A0;&#x22B8;&#x00A0;</tspan>;
            }
            else {
                return <tspan style={{ fill: "blue", fontWeight: "bold" }}>&#x00A0;&#x27DC;&#x00A0;</tspan>;
            }
        default:
            return " ";
    }
};

function getPinFunctions(pin, placement, isHideAllFunc) {
    var { pin_no, highlight_color, highlight_text } = pin;
    var texts = pin.texts.slice();
    var highlightText = <tspan key={pin_no} style={{fontWeight: "bold", fill: convertColorHex(highlight_color)}}>{highlight_text}</tspan>;

    const handleTexts = (ary) =>{
        for (let i = 0; i < ary.length; i++) {
            if(typeof ary[i] === "object") {
                if (i !== 0) {
                    ary[i-1] = ary[i-1] + ", ";
                }
            }
            else if (typeof ary[i] === "string") {
                if (i !== 0) {
                    ary[i] = ", " + ary[i];
                }
            }
        }
        return ary;
    }
    
    if (isHideAllFunc) {
        return highlightText;
    }
    else {
        texts.sort();
        let pinName = texts.filter(item => item.includes('.'))[0];
        if (pinName) {
            texts.splice(texts.indexOf(pinName), 1);
        }

        let matchIdx = texts.indexOf(highlight_text);
        if (matchIdx > -1) {
            texts[matchIdx] = highlightText;
        }
        else {
            pinName = highlightText;
        }

        if (texts.length === 0) {
            return highlightText
        }
        else if (placement === "bottom" || placement === "right") {
            if (pinName) {
                texts.unshift(pinName);
            }
            return handleTexts(texts);
        }
        else {
            if (pinName) {
                texts.push(pinName);
            }
            return handleTexts(texts);
        }
    }
};

function getPinFunctionsForBGA(pin, placement, isHideAllFunc) {
    var { highlight_color, highlight_text } = pin;
    var texts = pin.texts.slice();
    var highlightText = `<b><font color=${convertColorHex(highlight_color)}>${highlight_text}</font></b>`;

    const handleTexts = (ary) => {
        for (let i = 0; i < ary.length; i++) {
            if (ary[i].includes("</b>")) {
                continue;
            }
            else {
                ary[i] = `<font color=${convertColorHex(pin.normal_color)}>${ary[i]}</font>`;
            }
        }
        return ary.join("/ ");
    }

    if (isHideAllFunc) {
        return highlightText;
    }
    else {
        texts.sort();
        let pinName = texts.filter(item => item.includes('.'))[0];
        if (pinName) {
            texts.splice(texts.indexOf(pinName), 1);
        }

        let matchIdx = texts.indexOf(highlight_text);
        if (matchIdx > -1) {
            texts[matchIdx] = highlightText;
        }
        else {
            pinName = highlightText;
        }

        if (texts.length === 0) {
            return highlightText;
        }
        else if (placement === "bottom" || placement === "right") {
            if (pinName) {
                texts.unshift(pinName);
            }
            return handleTexts(texts);
        }
        else {
            if (pinName) {
                texts.push(pinName);
            }
            return handleTexts(texts);
        }
    }
};

function getPinDisplayText(pin, maxLength = 5) {
    const text = typeof pin === 'string' ? pin : String(pin ?? '');
    if (isGPIOPin(pin)) {
        return pin;
    }
    else if (text.length < maxLength) {
        return text;
    }
    else {
        return text.slice(0, maxLength - 2) + "...";
    }
};

function getPinDisplayTooltip(pin, maxLength = 5) {
    const text = typeof pin === 'string' ? pin : String(pin ?? '');
    if (isWPPin(pin) || isCCDBPin(pin) || isToolTipPin(pin)) {
        return getToolTipPinComment(pin);
    }
    if (isGPIOPin(pin)) {
        return "";
    }
    else if (text.length < maxLength) {
        return "";
    }
    else {
        return text;
    }
};

function genBottomPinCmp(positionX, positionY, indexRange, pins, isHideAllFunc) {
    if (!Array.isArray(indexRange) || !Array.isArray(pins) || pins.length === 0) {
        return
    }

    var tooltips = [];
    for (let i = 0; i < indexRange.length; i++) {
        let key = indexRange[i];
        let pin = pins[key - 1];
        tooltips.push(
            <Tooltip key={`g_pin${key}`} {...sharedTooltipProps(pin.information)}>
                <g transform={`translate(${positionX + i * 30}, ${positionY})`}>
                    <rect height="50" width="25" y="570" x="210" strokeWidth="1" fill={convertColorHex(pin.pin_bg_color)} />
                    <text transform="rotate(90 220 557)" y="560" x="210" strokeWidth="1" stroke={convertColorHex(pin.pin_no_color)}>{key}</text>
                    <text transform="rotate(90 220 557)" y="560" x="240" strokeWidth="0">{getPinStatus(pin)} {getPinDirection(pin, "bottom")}</text>
                    <text transform="rotate(90 220 557)" y="560" x="290" strokeWidth="0">{getPinFunctions(pin, "bottom", isHideAllFunc)}</text>
                </g>
            </Tooltip>
        );
    }

    return (<g stroke="#000">{tooltips}</g>);
};

