function genBGABottomIndex(positionX, positionY, indexRange) {
    if (typeof indexRange !== 'object') {
        return;
    }
    var index = [];
    for (let i = 0; i < indexRange.length; i++) {
        let key = indexRange[i];
        index.push(
            <text key={`bottomIndex-${i}`} x={positionX + 55 * i} y={positionY} strokeWidth="1" stroke="white">{key}</text>
        );
    }
    return (<g>{index}</g>);
};

function genBGALeftIndex(positionX, positionY, indexRange) {
    if (typeof indexRange !== 'object') {
        return;
    }
    var index = [];
    for (let i = 0; i < indexRange.length; i++) {
        let key = indexRange[i];
        index.push(
            <text key={`leftIndex-${i}`} x={positionX} y={positionY + 55 * i} strokeWidth="1" stroke="white">{key}</text>
        );
    }
    return (<g>{index}</g>);
};

function genBGACmp(positionX, positionY, indexRange, pins, isHideAllFunc) {
    function strSize(str) {
        var result = 8;
        if (typeof str !== "string") {
            return str;
        }
        else if (str.length < 10) {
            result = 18 - str.length;
        }
        return result;
    };

    if (!Array.isArray(indexRange) || !Array.isArray(pins) || pins.length === 0) {
        return
    }

    var tooltips = [];
    for (let i = 0; i < Math.pow(indexRange.length, 2); i++) {
        let quotient = Math.floor(i / indexRange.length);
        let remainder = (indexRange.length - 1) - (i % indexRange.length);
        let pin = pins[i];
        let newInfo = pin.information.replace(`<b>${pin.highlight_text}</b>`, getPinFunctionsForBGA(pin, "bottom", isHideAllFunc));

        tooltips.push(
            <Tooltip key={`g_pin${i}`} placement="right" {...sharedTooltipProps(newInfo)}>
                <g transform={`translate(${positionX + quotient * 55}, ${positionY + remainder * 55})`}>
                    <circle cx="0" cy="0" r="25" fill={convertColorHex(pin.pin_bg_color)} />
                    <text x="0" y="3" fontSize={strSize(pin.highlight_text)} textAnchor="middle" strokeWidth="1" stroke={convertColorHex(pin.highlight_color)}>{pin.highlight_text}</text>
                </g>
            </Tooltip>
        );
    }

    return (<g>{tooltips}</g>);
};

function genBGACmpV2(positionX, positionY, indexRange, data, isHideAllFunc) {
    const { pins = [], PinDescriptions = [], pinCurrentDescription = [] } = data || {};

    function strSize(str) {
        var result = 8;
        if (typeof str !== "string") {
            return result;
        }
        else if (str.length < 10) {
            result = 18 - str.length;
        }
        return result;
    };

    if (!Array.isArray(indexRange) || !Array.isArray(pins) || pins.length === 0) {
        return;
    }

    var tooltips = [];
    for (let i = 0; i < Math.pow(indexRange.length, 2); i++) {
        let quotient = Math.floor(i / indexRange.length);
        let remainder = (indexRange.length - 1) - (i % indexRange.length);
        let key = i + 1;
        let pin = pins?.[i] || "";
        let pinCurrent = pinCurrentDescription?.[i] || "";

        if (pin === "NC_ToolNotShow") {
            continue;
        }

        tooltips.push(
            <Tooltip key={`g_pin_v2_${i}`} placement="right" {...sharedTooltipProps(getPinDisplayTooltip(pinCurrent || pin, 7))}>
                <g transform={`translate(${positionX + quotient * 55}, ${positionY + remainder * 55})`}
                    className="pin-hit"
                    onClick={(e) => onPinClick && onPinClick(e, key, pin, PinDescriptions)}
                >
                    <circle
                        className="pin-shape" cx="0" cy="0" r="25" fill={getPinColor(pin, pinCurrent)}
                    />
                    <text
                        x="0" y="3" fontSize={strSize(pin)} textAnchor="middle" strokeWidth="1"
                    >
                        {getPinDisplayText(pinCurrent || pin, 7)}
                    </text>
                </g>
            </Tooltip>
        );
    }

    return (<g>{tooltips}</g>);
};


