function onPinClick(e, key, pin, PinDescriptions) {
    if (!isGPIOPin(pin) && !isWPPin(pin) && !isCCDBPin(pin) && !isToolTipPin(pin)) {
        return;
    }
    const rect = e.currentTarget.getBoundingClientRect();
    window.dispatchEvent(new CustomEvent('pin-context-menu', {
        detail: { x: rect.right, y: rect.top, key, pin, PinDescriptions }
    }));
}

function getPinColor(pin, pinCurrent) {
    if (isWPPin(pin) || isCCDBPin(pin) || isToolTipPin(pin)) {
        return g_colorForTooltipOnHover;
    }
    else if (pinCurrent !== "") {
        return g_colorForConfiguredByUser;
    }
    else if (isGPIOPin(pin)) {
        return '#FFFFFF';
    }
    else {
        return g_colorForNotGPIO;
    }
}