import React from "react";
import ReactDOM from "react-dom/client";
import { Provider } from 'react-redux';
import { Modal, notification } from 'antd';
import App from './App.tsx';
import store from "./store";
import './index.css';
import './i18n'

import Toolbar from './components/Toolbar';
import ChipSeries from './components/ChipSeries';
import PartNo from './components/PartNo';

const toHtmlContent = (content: any) => {
  if (typeof content === "string") {
    content = content.replaceAll("\n", "<br/>");
  }

  try {
    return <div dangerouslySetInnerHTML={{ __html: `${content}` }} />;
  }
  catch (e) {
    console.error(e);
    return content;
  }
};

EXPORT_REACT.info = (title: any, content: any) => Modal.info({
  title: title,
  content: toHtmlContent(content),
  centered: true,
});

EXPORT_REACT.warning = (title: any, content: any) => Modal.warning({
  title: title,
  content: toHtmlContent(content),
  centered: true,
});

EXPORT_REACT.error = (title: any, content: any) => Modal.error({
  title: title,
  content: toHtmlContent(content),
  centered: true,
});

EXPORT_REACT.notification_warning = (title: any, content: any, duration?: number) => notification.warning({
  message: title || "Waning",
  description: toHtmlContent(content),
  placement: 'bottomRight',
  duration: duration || null,
  style: {
    inlineSize: "max-content",
    minWidth: 530,
  },
});

EXPORT_REACT.notification_error = (title: any, content: any, duration?: number) => notification.error({
  message: title || "Error",
  description: toHtmlContent(content),
  placement: 'bottomRight',
  duration: null,
  style: {
    inlineSize: "max-content",
    minWidth: 530,
  },
});

EXPORT_REACT._D = (msg: any) => {
  // TODO
  return;
  if (!g_bReadyForRelease) {
    console.warn(msg);
  }
};

const topToolBar = ReactDOM.createRoot(
  document.getElementById('topToolBar') as HTMLElement
);
topToolBar.render(
  <Provider store={store}>
    <Toolbar />
  </Provider>
);

