// Select item from NUTOOL_PER.g_cfg_perFunctions
import { createSlice } from "@reduxjs/toolkit";
import {
    naturalSort,
} from '../../libs/pinconfig-libs';
const initialState = [];

const r_module_functions = createSlice({
    name: "r_module_functions",
    initialState,
    reducers: {
        set_module_functions(state, action) {
            state = action.payload;
            return state;
        }
    }
});

export const { set_module_functions } = r_module_functions.actions;
export default r_module_functions.reducer;