import { Layout } from 'antd';
import * as React from 'react';
import { useSelector } from "react-redux";
import './App.css';

import ChipSeries from './components/ChipSeries';
import PartNo from './components/PartNo';
import MFPRegisterTree from './components/MFPRegisterTree';
import ModuleTree from './components/ModuleTree';
import PinConfigView from './components/PinConfigView';
import PinContextMenu from './components/PinContextMenu';

const { Header, Sider, Content } = Layout;

function App() {
  const r_settings_hideLogs = useSelector((state: any) => state.r_settings_hideLogs);
  const r_logs = useSelector((state: any) => state.r_logs);
  const [showMFPTree, setShowMFPTree] = React.useState(true);

  return (
    <Layout className="root-layout">
      <Sider width={250} collapsible collapsedWidth={0}>
        <Header className='layout-silder-header'>
          <ChipSeries />
          <PartNo />
        </Header>
        <Content className="sider-content">
          <MFPRegisterTree showMFPTree={showMFPTree} setShowMFPTree={setShowMFPTree} />
          <ModuleTree showMFPTree={showMFPTree} />
        </Content>
      </Sider>
      <Content className='layout-content'>
        <PinConfigView />
      </Content>
      <PinContextMenu />
    </Layout>
  )
}

export default App;
