import React, { useMemo, useEffect, useState, useRef, useCallback } from 'react'
import { useDispatch, useSelector } from "react-redux";
import { useTranslation } from 'react-i18next';
import {
	Layout,
	Tree,
	Modal,
	Input,
	Tooltip,
} from 'antd';
import { DatabaseFilled } from '@ant-design/icons';

import {
	naturalSort,
	update_gpio_MFPs,
	updatePinName,
} from '../libs/pinconfig-libs';

import {
	getGpioDescription,
} from '../content-web-commonLib';

import { setPinCurrentDescription } from "../store/slices/r_pinCurrentDescription";
import { setMfpRegisterName } from "../store/slices/r_mfpRegisterName";
import './PeripheralFunctions.css';

const { Header, Content } = Layout;

const convertCheckedKeysToPinDescriptions = (checkedKeys = [], pinCount = 0) => {
	const result = Array.from({ length: pinCount }, () => '');

	checkedKeys.forEach((item) => {
		if (typeof item !== 'string') {
			return;
		}

		const matched = item.match(/^(.*)_Pin(\d+)$/);
		if (!matched) {
			return;
		}

		const pinFunction = matched[1];
		const pinIndex = Number(matched[2]) - 1;

		if (pinIndex >= 0 && pinIndex < pinCount) {
			result[pinIndex] = pinFunction;
		}
	});

	return result;
};

const highlightText = (text, search) => {
	if (!search || search.length < 2 || typeof text !== 'string') return text;
	const lowerText = text.toLowerCase();
	const lowerSearch = search.toLowerCase();
	const index = lowerText.indexOf(lowerSearch);
	if (index === -1) return text;
	return (
		<>
			{text.slice(0, index)}
			<span style={{ backgroundColor: 'yellow' }}>{text.slice(index, index + search.length)}</span>
			{text.slice(index + search.length)}
		</>
	);
};

const ModuleTree = (props) => {
	const { t } = useTranslation();
	const dispatch = useDispatch();
	const [modal, contextHolder] = Modal.useModal();
	const r_module_functions = useSelector((state) => state.r_module_functions);
	const r_mfpRegisterName = useSelector((state) => state.r_mfpRegisterName);
	const r_pinCurrentDescription = useSelector((state) => state.r_pinCurrentDescription);
	const { showMFPTree} = props;
	const [expandedKeys, setExpandedKeys] = useState([]);
	const [searchValue, setSearchValue] = useState('');
	const [pendingScrollKey, setPendingScrollKey] = useState(null);
	const checkedKeysRef = useRef([]);
	const treeRef = useRef(null);
	const matchKeysRef = useRef([]);
	const matchIndexRef = useRef(-1);
	const lastSearchRef = useRef('');

	const getSubNodeBaseName = (subNodeName) => {
		if (typeof subNodeName !== 'string') {
			return '';
		}
		const pinIndex = subNodeName.lastIndexOf('_Pin');
		return pinIndex > -1 ? subNodeName.slice(0, pinIndex) : subNodeName;
	};
	const getSubNodePin = (subNodeName) => {
		if (typeof subNodeName !== 'string') {
			return '';
		}
		const pinIndex = subNodeName.lastIndexOf('_Pin');
		return pinIndex > -1 ? subNodeName.slice(pinIndex + 4) : '';
	};

	const handleCheck = (checkedKeys, info) => {
		g_pinCurrentDescription = structuredClone(r_pinCurrentDescription);
		const { children, className, key } = info.node;
		const checkSinglePinNode = (checkedKeys, key, className, bforce) => {
			const prefix = key.slicePriorToX('_Pin');
			if (bforce || !bConflictNode(key)) {
				if (className === "custom-ant-tree-radio") {
					const anotherCheckedKey = checkedKeys.filter(tmp =>
						(key !== tmp && tmp.startsWith(prefix) && !tmp.endsWith("_Intermediate") && !tmp.endsWith("_Root"))
					)[0];
					if (anotherCheckedKey) {
						const index = getSubNodePin(anotherCheckedKey) - 1;
						update_gpio_MFPs(index, NUTOOL_PIN.g_cfg_pkgs[NUTOOL_PIN.g_packageNumberIndex][index]);
					}
					// Only one module can be selected
					checkedKeys = checkedKeys.filter(tmp =>
						(key === tmp || prefix !== tmp.slicePriorToX('_Pin'))
					);
				}
				update_gpio_MFPs(getSubNodePin(key) - 1, key.restorePinTreeNodeName(), true);
				dispatch(setMfpRegisterName(Object.assign([], g_gpio_MFPs)));
				dispatch(setPinCurrentDescription(
					convertCheckedKeysToPinDescriptions(checkedKeys, r_pinCurrentDescription.length)
				));
				return checkedKeys;
			}
			else {
				modal.confirm({
					title: 'Pin Conflict',
					content: `Pin ${getSubNodePin(key)} is already assigned to "${r_pinCurrentDescription[getSubNodePin(key) - 1]}". Do you want to replace it with "${prefix}"?`,
					okText: 'Yes',
					cancelText: 'No',
					onOk() {
						if (className === "custom-ant-tree-radio") {
							const radioNode = checkedKeys.filter(tmp =>
								(key !== tmp && tmp.startsWith(prefix) && !tmp.endsWith("_Intermediate"))
							)[0];
							if (radioNode) {
								const index = getSubNodePin(radioNode) - 1;
								update_gpio_MFPs(index, NUTOOL_PIN.g_cfg_pkgs[NUTOOL_PIN.g_packageNumberIndex][index]);
							}
							// Only one module can be selected
							checkedKeys = checkedKeys.filter(tmp =>
								(key === tmp || prefix !== tmp.slicePriorToX('_Pin'))
							);
						}
						update_gpio_MFPs(getSubNodePin(key) - 1, key.restorePinTreeNodeName(), true);
						dispatch(setMfpRegisterName(Object.assign([], g_gpio_MFPs)));
						dispatch(setPinCurrentDescription(
							convertCheckedKeysToPinDescriptions(checkedKeys, r_pinCurrentDescription.length)
						));
					},
					onCancel() {
						return;
					},
				});
			}
		};

		if (info.checked) {
			if (key.endsWith('_Root')) {
				const conflictNodes = children.filter((child) => bConflictNode(child.key));
				if (conflictNodes.length > 0) {
					modal.confirm({
						title: 'Pin Conflict',
						content: `Some Pins are already assigned. Do you want to continue?`,
						okText: 'Yes',
						cancelText: 'No',
						onOk() {
							let usedPins = [];
							// '_Pin'
							children.filter(
								(child) => !child.key.endsWith('_Intermediate')
							).forEach((child) => {
								checkedKeys = checkSinglePinNode(checkedKeys, child.key, child.className, true) ?? checkedKeys;
								usedPins.push(getSubNodePin(child.key));
							});
							const intermediateNode = children.filter(
								(child) => child.key.endsWith('_Intermediate')
							);
							for (let i = 0; i < intermediateNode.length; i += 1) {
								const prefix = intermediateNode[i].key.slicePriorToX('_Intermediate');
								const index = r_pinCurrentDescription.indexOf(prefix);
								if (index > -1) {
									// NOOP: Pin(radioNode) already selected, but checkSinglePinNode will unselect it, so we need to select it again.
									const radioNode = intermediateNode[i].children.find((node) => (node.key === `${prefix}_Pin${index + 1}`));
									checkedKeys = checkSinglePinNode(checkedKeys, radioNode.key, radioNode.className, true) ?? checkedKeys;
								}
								else {
									const _children = intermediateNode[i].children;
									const unconflictNode = _children.find(
										(child) => !bConflictNode(child.key) && !usedPins.includes(getSubNodePin(child.key))
									);
									if (unconflictNode) {
										checkedKeys = checkSinglePinNode(checkedKeys, unconflictNode.key, unconflictNode.className, true) ?? checkedKeys;
									}
									else {
										checkedKeys = checkSinglePinNode(checkedKeys, _children[0].key, _children[0].className, true) ?? checkedKeys;
									}
								}
							}
						},
						onCancel() {
							return;
						},
					});
				}
				else {
					let usedPins = [];
					// '_Pin'
					children.filter(
						(child) => !child.key.endsWith('_Intermediate')
					).forEach((child) => {
						usedPins.push(getSubNodePin(child.key));
						checkedKeys = checkSinglePinNode(checkedKeys, child.key, child.className) ?? checkedKeys;
					});
					// '_Intermediate'
					const intermediateNodes = children.filter(
						(child) => child.key.endsWith('_Intermediate')
					);
					for (let i = 0; i < intermediateNodes.length; i += 1) { 
						const prefix = intermediateNodes[i].key.slicePriorToX('_Intermediate');
						const index = r_pinCurrentDescription.indexOf(prefix);
						if (index > -1) {
							// NOOP: Pin(radioNode) already selected, but checkSinglePinNode will unselect it, so we need to select it again.
							const radioNode = intermediateNodes[i].children.find(
								(node) => (node.key === `${prefix}_Pin${index + 1}`)
							);
							checkedKeys = checkSinglePinNode(checkedKeys, radioNode.key, radioNode.className) ?? checkedKeys;
						}
						else {
							const _children = intermediateNodes[i].children;
							const unconflictNode = _children.find((child) => 
								!bConflictNode(child.key) && !usedPins.includes(getSubNodePin(child.key))
							);
							if (unconflictNode) {
								checkedKeys = checkSinglePinNode(checkedKeys, unconflictNode.key, unconflictNode.className) ?? checkedKeys;
							}
							else {
								checkedKeys = checkSinglePinNode(checkedKeys, _children[0].key, _children[0].className) ?? checkedKeys;
							}
						}
					}
				}
			}
			else if (key.endsWith('_Intermediate')) {
				const prefix = key.slicePriorToX('_Intermediate');
				const index = r_pinCurrentDescription.indexOf(prefix);
				if (index > -1) {
					// NOOP: Pin(radioNode) already selected, nothing to do.
				}
				else {
					const unconflictNode = children.filter(
						(child) => !bConflictNode(child.key)
					)[0];
					if (unconflictNode) {
						checkSinglePinNode(checkedKeys, unconflictNode.key, unconflictNode.className);
					}
					else {
						checkSinglePinNode(checkedKeys, children[0].key, children[0].className);
					}
				}
			}
			// "_Pin"
			else {
				checkSinglePinNode(checkedKeys, key, className);
			}
		}
		else {
			if (key.endsWith('_Root')) {
				for (let i = 0; i < children.length; i += 1) {
					const index = getSubNodePin(children[i].key) - 1;
					update_gpio_MFPs(index, NUTOOL_PIN.g_cfg_pkgs[NUTOOL_PIN.g_packageNumberIndex][index]);
				}
			}
			// else if (key.endsWith('_Intermediate')) {
			// }
			// '_Pin'
			else {
				const index = getSubNodePin(key) - 1;
				update_gpio_MFPs(index, NUTOOL_PIN.g_cfg_pkgs[NUTOOL_PIN.g_packageNumberIndex][index]);
			}
			dispatch(setMfpRegisterName(Object.assign([], g_gpio_MFPs)));
			dispatch(setPinCurrentDescription(
				convertCheckedKeysToPinDescriptions(checkedKeys, r_pinCurrentDescription.length)
			));
		}
	};

	const _checkedKeys = useMemo(() => {
		const keys = [];
		r_pinCurrentDescription.forEach(function (val, idx) {
			if (val) {
				keys.push(`${val}_Pin${idx + 1}`);
			}
		});
		return keys;
	}, [r_pinCurrentDescription]);

	const getExpandedKeysFromChecked = (treeNodes, checkedKeys) => {
		const checkedSet = new Set(checkedKeys);
		const expandedSet = new Set();

		const traverse = (nodes, parentPath = []) => {
			nodes.forEach((node) => {
				const currentPath = [...parentPath, node.key];
				if (checkedSet.has(node.key)) {
					parentPath.forEach((k) => expandedSet.add(k));
				}
				if (Array.isArray(node.children) && node.children.length > 0) {
					traverse(node.children, currentPath);
				}
			});
		};

		traverse(treeNodes);
		return Array.from(expandedSet);
	};

	const findTreeNodeByKey = (nodes, targetKey) => {
		for (let i = 0; i < nodes.length; i += 1) {
			const node = nodes[i];
			if (node.key === targetKey) {
				return node;
			}
			if (Array.isArray(node.children) && node.children.length > 0) {
				const matched = findTreeNodeByKey(node.children, targetKey);
				if (matched) {
					return matched;
				}
			}
		}
		return null;
	};

	const collectSubtreeKeys = (node) => {
		const keys = [];
		const walk = (n) => {
			keys.push(n.key);
			if (Array.isArray(n.children) && n.children.length > 0) {
				n.children.forEach((child) => walk(child));
			}
		};
		walk(node);
		return keys;
	};

	const bConflictNode = (pin) => {
		const pinIndex = getSubNodePin(pin) - 1;
		const pinName = r_pinCurrentDescription[pinIndex];
		if (pin.endsWith('_Intermediate')) {
			const rootNode = treeData.find((data) => data.key === pin.slicePriorToX('_') + '_Root');
			if (!rootNode) return false;
			const intermediateNode = rootNode.children.find((child) => child.key === pin);
			if (!intermediateNode) return false;
			const unconflictNode = intermediateNode.children.find((child) => !bConflictNode(child.key));
			return unconflictNode ? false : true;
		}
		else {
			if (pinName !== "" && !pin.startsWith(pinName)) {
				return true
			}
			else {
				return false;
			}
		}
	};

	const getPinWithStatus = (subNodeName) => {
		const baseName = getSubNodeBaseName(subNodeName);
		const pinText = `${baseName} (Pin:${updatePinName(getSubNodePin(subNodeName))})`;
		const content = highlightText(pinText, searchValue);
		const span = bConflictNode(subNodeName)
			? <span style={{ color: 'red' }}>{content}</span>
			: <span>{content}</span>;
		const desc = getGpioDescription(baseName);
		return desc
			? <Tooltip title={desc} placement="right" color="#ffffe1" overlayInnerStyle={{ color: 'black' }}>{span}</Tooltip>
			: span;
	};
		
	const treeData = useMemo(() => {
		if (!r_module_functions) {
			return [];
		}

		const isArrayIndexKey = (key) => String(Number(key)) === key;
		
		let moduleNames = [];

		if (Array.isArray(r_module_functions)) {
			moduleNames = Object.keys(r_module_functions).filter((key) => !isArrayIndexKey(key));
		} else if (typeof r_module_functions === 'object') {
			moduleNames = Object.keys(r_module_functions);
		}

		moduleNames.sort(naturalSort);

		return moduleNames.map((moduleName) => {
			const functions = r_module_functions[moduleName];
			const modulePinsMap = globalThis?.g_module_pins || {};
			const modulePins = Array.isArray(modulePinsMap[moduleName]) ? modulePinsMap[moduleName] : [];
			const subNodeNameArray = [];

			if (Array.isArray(functions) && modulePins.length > 0) {
				for (let j = 0, maxJ = modulePins.length; j < maxJ; j += 1) {
					const subNodeName = functions[j];
					if (!subNodeName) {
						continue;
					}
					subNodeNameArray.push(`${String(subNodeName)}_Pin${modulePins[j]}`);
				}
			} else if (Array.isArray(functions)) {
				functions.forEach((functionName) => {
					if (!functionName) {
						return;
					}
					subNodeNameArray.push(String(functionName));
				});
			}

			subNodeNameArray.sort(naturalSort);

			const skippedIndexSet = new Set();
			const children = [];

			for (let j = 0; j < subNodeNameArray.length; j += 1) {
				if (skippedIndexSet.has(j)) {
					continue;
				}

				const subNodeName = subNodeNameArray[j];
				const baseName = getSubNodeBaseName(subNodeName);
				const identicalIndexes = [];

				for (let k = j + 1; k < subNodeNameArray.length; k += 1) {
					if (getSubNodeBaseName(subNodeNameArray[k]) === baseName) {
						identicalIndexes.push(k);
						skippedIndexSet.add(k);
					}
				}

				if (identicalIndexes.length === 0) {
					children.push({
						title: getPinWithStatus(subNodeName),
						// id: `${moduleName}-${subNodeName}-${j}`,
						key: `${subNodeName}`,
						isLeaf: true,
					});
				} else {
					const groupChildren = [j, ...identicalIndexes].map((idx) => {
						const name = subNodeNameArray[idx];
						const pin = getSubNodePin(name);
						g_disabledLeafNodesArray.push(`${name}`);
						return {
							title: getPinWithStatus(name),
							// title: pin ? `Pin:${pin}` : name,
							// id: `${moduleName}-${name}-${idx}`,
							key: `${name}`,
							className: 'custom-ant-tree-radio',
							isLeaf: true,
						};
					});

					const intermediateDesc = getGpioDescription(baseName);
					const intermediateText = highlightText(baseName, searchValue);
					children.push({
						title: intermediateDesc
							? <Tooltip title={intermediateDesc} placement="right" color="#ffffe1" overlayInnerStyle={{ color: 'black' }}>{intermediateText}</Tooltip>
							: intermediateText,
						// id: `${moduleName}-${baseName}-Intermediate-${j}`,
						key: `${baseName}_Intermediate`,
						children: groupChildren,
					});
					g_disabledSubNodesArray.push(`${baseName}_Intermediate`);
				}
			}

			const rootDesc = getGpioDescription(moduleName);
			const rootText = highlightText(moduleName, searchValue);
			return {
				title: <Tooltip title={rootDesc || moduleName} placement="right" color="#ffffe1" overlayInnerStyle={{ color: 'black' }}>{rootText}</Tooltip>,
				key: `${moduleName}_Root`,
				icon: <DatabaseFilled className="custom-ant-tree-icon" />,
				children,
			};
		});
	}, [r_module_functions, r_mfpRegisterName, r_pinCurrentDescription, searchValue]);

	useEffect(() => {
		checkedKeysRef.current = _checkedKeys;
		const autoExpandedKeys = getExpandedKeysFromChecked(treeData, _checkedKeys);
		setExpandedKeys((prev) => Array.from(new Set([...prev, ...autoExpandedKeys])));
	}, [treeData, _checkedKeys]);

	useEffect(() => {
		const triggerModuleTreeCheck = (nodeKey, checked = true) => {
			if (!nodeKey) {
				return;
			}

			const node = findTreeNodeByKey(treeData, nodeKey);
			if (!node) {
				return;
			}

			// 使用 ref 累積 key，避免連續呼叫時 React state 尚未更新導致覆蓋
			const keySet = new Set(checkedKeysRef.current);
			const subtreeKeys = collectSubtreeKeys(node);

			if (checked) {
				subtreeKeys.forEach((k) => keySet.add(k));
			} else {
				subtreeKeys.forEach((k) => keySet.delete(k));
			}

			const newKeys = Array.from(keySet);
			checkedKeysRef.current = newKeys;

			handleCheck(newKeys, {
				checked,
				node,
			});
		};

		globalThis.triggerModuleTreeCheck = triggerModuleTreeCheck;

		return () => {
			if (globalThis.triggerModuleTreeCheck === triggerModuleTreeCheck) {
				delete globalThis.triggerModuleTreeCheck;
			}
		};
	}, [treeData, _checkedKeys, handleCheck]);

	useEffect(() => {
		if (!pendingScrollKey) return;
		setPendingScrollKey(null);

		// Wait for Tree to finish expanding and rendering
		requestAnimationFrame(() => {
			requestAnimationFrame(() => {
				// Method 1: Tree built-in scrollTo (may not work in all versions)
				treeRef.current?.scrollTo({ key: pendingScrollKey, align: 'top' });

				// Method 2: DOM fallback – find first yellow-highlighted span and scroll it into view
				setTimeout(() => {
					const treeContent = document.querySelector('#module-tree .module-tree-content');
					const firstHighlight = document.querySelector(
						'#module-tree span[style*="background-color: yellow"],' +
						'#module-tree span[style*="background-color:yellow"]'
					);
					if (firstHighlight) {
						const nodeEl = firstHighlight.closest('.ant-tree-treenode');
						if (nodeEl) {
							nodeEl.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
						}
					}
				}, 50);
			});
		});
	}, [expandedKeys, pendingScrollKey]);

	const handleSearch = useCallback((value) => {
		const trimmed = value.trim();
		setSearchValue(trimmed);
		if (!trimmed || trimmed.length < 2 || /^\d+$/.test(trimmed)) {
			matchKeysRef.current = [];
			matchIndexRef.current = -1;
			lastSearchRef.current = '';
			return;
		}

		const lowerVal = trimmed.toLowerCase();

		// Same value: scroll directly to next match (bypasses React state to avoid batching issues)
		if (trimmed === lastSearchRef.current && matchKeysRef.current.length > 0) {
			const idx = (matchIndexRef.current + 1) % matchKeysRef.current.length;
			matchIndexRef.current = idx;
			const targetKey = matchKeysRef.current[idx];
			requestAnimationFrame(() => requestAnimationFrame(() => {
				treeRef.current?.scrollTo({ key: targetKey, align: 'top' });
				setTimeout(() => {
					const all = document.querySelectorAll(
						'#module-tree span[style*="background-color: yellow"],' +
						'#module-tree span[style*="background-color:yellow"]'
					);
					const nodeEl = (all[idx] ?? all[0])?.closest('.ant-tree-treenode');
					nodeEl?.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
				}, 50);
			}));
			return;
		}

		// New value: collect all matches and expand their parents
		lastSearchRef.current = trimmed;
		const newMatchKeys = [];
		const keysToExpand = [];

		for (const rootNode of treeData) {
			const rootName = rootNode.key.replace('_Root', '').toLowerCase();
			let rootMatched = false;

			if (rootName.includes(lowerVal)) {
				newMatchKeys.push(rootNode.key);
				keysToExpand.push(rootNode.key);
				rootMatched = true;
			}

			for (const child of (rootNode.children || [])) {
				if (child.isLeaf) {
					if (child.key.toLowerCase().includes(lowerVal)) {
						newMatchKeys.push(child.key);
						if (!rootMatched) keysToExpand.push(rootNode.key);
						rootMatched = true;
					}
				} else {
					const intermediateName = child.key.replace('_Intermediate', '').toLowerCase();
					let intermediateMatched = false;
					if (intermediateName.includes(lowerVal)) {
						newMatchKeys.push(child.key);
						if (!rootMatched) keysToExpand.push(rootNode.key);
						keysToExpand.push(child.key);
						rootMatched = true;
						intermediateMatched = true;
					}
					for (const grandChild of (child.children || [])) {
						if (grandChild.key.toLowerCase().includes(lowerVal)) {
							newMatchKeys.push(grandChild.key);
							if (!rootMatched) keysToExpand.push(rootNode.key);
							if (!intermediateMatched) keysToExpand.push(child.key);
							rootMatched = true;
							intermediateMatched = true;
						}
					}
				}
			}
		}

		matchKeysRef.current = newMatchKeys;
		matchIndexRef.current = 0;

		if (newMatchKeys.length > 0) {
			setExpandedKeys(prev => Array.from(new Set([...prev, ...keysToExpand])));
			setPendingScrollKey(newMatchKeys[0]);
		}
	}, [treeData]);

	return (
		<Layout id={"module-tree"} style={{ flex: 1, minHeight: 0, overflow: 'hidden' }}>
			{contextHolder}
			<Header className='leftpanel-header'>
				<div style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
					<b style={{ flexShrink: 0 }}>{t("LBL_SUPPORTED_MODULES")}</b>
					<Input.Search
						onSearch={handleSearch}
						allowClear
						size="small"
					/>
				</div>
			</Header>
			<Content className='module-tree-content' style={{ flex: 1, minHeight: 0 }}>
				<Tree
					ref={treeRef}
					showLine
					showIcon
					checkable
					expandedKeys={expandedKeys}
					onExpand={(keys) => setExpandedKeys(keys)}
					checkedKeys={_checkedKeys}
					onCheck={handleCheck}

					treeData={treeData}
				/>
			</Content>
		</Layout>
	);
};

export default ModuleTree;