import React, { useMemo, useState, useCallback, useRef } from 'react'
import { useSelector, useDispatch } from "react-redux";
import { useTranslation } from 'react-i18next';
import {
	Layout,
	Tree,
	Switch,
} from 'antd';

import {
	decimalToHex,
	checkNodesByMFPregister,
	uncheckNodesByMFPregister,
} from '../libs/pinconfig-libs';

import { setMfpRegisterName } from "../store/slices/r_mfpRegisterName";
import './PeripheralFunctions.css';

const { Header, Content } = Layout;

const MFPRegisterTree = (props) => {
	const { t } = useTranslation();
	const r_mfpRegisterName = useSelector((state) => state.r_mfpRegisterName);
	const { showMFPTree, setShowMFPTree } = props;
	const dispatch = useDispatch();
	const [editingKey, setEditingKey] = useState(null);
	const [editingValue, setEditingValue] = useState('');
	const editingValueRef = useRef('');

	const handleDblClick = useCallback((e, name, hexStr) => {
		e.stopPropagation();
		setEditingKey(name);
		setEditingValue(hexStr);
		editingValueRef.current = hexStr;
	}, []);

	const handleInputChange = useCallback((e) => {
		const val = e.target.value.replace(/[^0-9a-fA-F]/g, '').slice(0, 8);
		setEditingValue(val);
		editingValueRef.current = val;
	}, []);

	const commitEdit = useCallback((name, oldNumValue) => {
		const rawHex = editingValueRef.current;
		const hex8 = rawHex.padStart(8, '0').toUpperCase();
		const newNumValue = parseInt(hex8, 16);

		// Reset edit state first
		setEditingKey(null);
		setEditingValue('');
		editingValueRef.current = '';

		if (newNumValue === oldNumValue) return;

		const fullRegStr = `${name}:0x${hex8.toLowerCase()}`;

		// Validate using NUTOOL_PIN.verifyMFPName, fallback to non-empty check
		const isValid = (typeof NUTOOL_PIN !== 'undefined' && typeof NUTOOL_PIN.verifyMFPName === 'function')
			? NUTOOL_PIN.verifyMFPName(fullRegStr)
			: rawHex.length > 0;

		if (!isValid) return; // revert silently

		if (typeof globalThis.g_gpio_MFPs !== 'undefined') {
			const oldRegStr = `${name}:0x${decimalToHex(oldNumValue)}`;
			// Uncheck pins associated with old register value
			uncheckNodesByMFPregister(oldRegStr);

			// Update global register value
			globalThis.g_gpio_MFPs[name] = newNumValue;
			// Re-check pins based on new register value; returns corrected string with invalid bits cleared
			const result = checkNodesByMFPregister(fullRegStr);
			// Apply the corrected value back (bits for non-existent pins are cleared)
			const correctedHex = result.slice(result.indexOf('0x') + 2);
			globalThis.g_gpio_MFPs[name] = parseInt(correctedHex, 16);
		}
		dispatch(setMfpRegisterName(Object.assign([], globalThis.g_gpio_MFPs || {})));
	}, [dispatch]);

	const handleKeyDown = useCallback((e, name, numValue) => {
		if (e.key === 'Enter') { e.preventDefault(); commitEdit(name, numValue); }
		if (e.key === 'Escape') { setEditingKey(null); setEditingValue(''); editingValueRef.current = ''; }
	}, [commitEdit]);

	const renderTitle = useCallback((nodeData) => {
		const { key: name, _numValue: numValue = 0 } = nodeData;
		const hexStr = decimalToHex(numValue);
		return (
			<span style={{ fontFamily: 'Consolas, "Courier New", monospace' }}>
				<span style={{ display: 'inline-block', width: '14ch' }}>{name}:</span>
				{editingKey === name ? (
					<>
						<span>0x</span>
						<input
							value={editingValue}
							onChange={handleInputChange}
							onBlur={() => commitEdit(name, numValue)}
							onKeyDown={(e) => handleKeyDown(e, name, numValue)}
							onFocus={(e) => e.stopPropagation()}
							style={{
								width: '9ch',
								fontFamily: 'Consolas, "Courier New", monospace',
								backgroundColor: '#fff',
							}}
							autoFocus
						/>
					</>
				) : (
					<span
						onDoubleClick={(e) => handleDblClick(e, name, hexStr)}
						style={{ cursor: 'text' }}
						title={name && typeof NUTOOL_PIN !== 'undefined' && NUTOOL_PIN.g_cfg_regDescriptions?.[name] ? NUTOOL_PIN.g_cfg_regDescriptions[name] : ''}
					>
						0x{hexStr}
					</span>
				)}
			</span>
		);
	}, [editingKey, editingValue, handleInputChange, commitEdit, handleKeyDown, handleDblClick]);

	const treeData = useMemo(() => {
		let registerItems = [];

		const isArrayIndexKey = (key) => String(Number(key)) === key;

		if (Array.isArray(r_mfpRegisterName)) {
			const itemsFromIndexes = r_mfpRegisterName.map((item) => {
				if (typeof item === 'string') {
					return { name: item, value: 0 };
				}
				if (item && typeof item === 'object') {
					const name = Object.keys(item)[0] || '';
					return { name, value: Number(item[name]) || 0 };
				}
				return null;
			}).filter(Boolean);

			// Support array with named properties, e.g. [GPE_MFPH: 0, GPC_MFPH: 0]
			const itemsFromNamedProps = Object.keys(r_mfpRegisterName)
				.filter((key) => !isArrayIndexKey(key))
				.map((key) => ({
					name: key,
					value: Number(r_mfpRegisterName[key]) || 0,
				}));

			if (!(g_chipType === "KM1M7CF" || g_chipType === "KM1M7CF4/5")) {
				itemsFromNamedProps.sort((a, b) =>
					a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: 'base' })
				);
			}

			registerItems = [...itemsFromIndexes, ...itemsFromNamedProps];
		} else if (r_mfpRegisterName && typeof r_mfpRegisterName === 'object') {
			registerItems = Object.keys(r_mfpRegisterName).map((name) => ({
				name,
				value: Number(r_mfpRegisterName[name]) || 0,
			}));
		}

		return registerItems.map(({ name, value }) => ({
			title: name,
			key: name,
			isLeaf: true,
			_numValue: value,
		}));
	}, [r_mfpRegisterName]);

	return (
		<Layout style={{ flex: '0 0 auto' }}>
			<Header className='leftpanel-header'>
				<div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
					<b>{t("LBL_MFP_REGISTERS")}</b>
					<Switch
						checked={showMFPTree}
						onChange={setShowMFPTree}
						checkedChildren="Expand"
						unCheckedChildren="Collapse"
					/>
				</div>
			</Header>
			<Content className='mfp-register-tree-content'>
				{showMFPTree ? (
					<Tree
						showLine
						showIcon
						treeData={treeData}
						titleRender={renderTitle}
					/>
				) : null}
			</Content>
		</Layout>
	);
};

export default MFPRegisterTree;