import React, { useState, useEffect, useRef } from 'react';
import { useDispatch, useSelector } from "react-redux";
import { Menu, ConfigProvider, Tooltip } from 'antd';

import {
    update_gpio_MFPs,
} from '../libs/pinconfig-libs';

import {
    getGpioDescription,
} from '../content-web-commonLib';

import { setMfpRegisterName } from "../store/slices/r_mfpRegisterName";
import { setPinCurrentDescription } from "../store/slices/r_pinCurrentDescription";

const MENU_WIDTH = 180;

const PinContextMenu = () => {
    const [menuState, setMenuState] = useState({ visible: false, x: 0, y: 0, key: null, pin: null, PinDescriptions: null });
    const menuRef = useRef(null);
    const r_pinCurrentDescription = useSelector((state) => state.r_pinCurrentDescription);
    const dispatch = useDispatch();

    useEffect(() => {
        const handler = (e) => {
            const { x, y, key, pin, PinDescriptions } = e.detail;
            // 邊界修正：若右側不夠，往左偏移
            const adjustedX = x + MENU_WIDTH > window.innerWidth ? window.innerWidth - MENU_WIDTH - 8 : x;
            setMenuState({ visible: true, x: adjustedX, y, key, pin, PinDescriptions });
        };
        window.addEventListener('pin-context-menu', handler);
        return () => window.removeEventListener('pin-context-menu', handler);
    }, []);

    // 顯示後再修正底部超出
    useEffect(() => {
        if (menuState.visible && menuRef.current) {
            const rect = menuRef.current.getBoundingClientRect();
            if (rect.bottom > window.innerHeight) {
                setMenuState((s) => ({ ...s, y: window.innerHeight - rect.height - 8 }));
            }
        }
    }, [menuState.visible, menuState.x, menuState.y]);

    const handleMenuClick = ({ key: menuKey }) => {
        let result = Object.assign([], r_pinCurrentDescription);
        console.log('menu action:', menuKey, 'pin:', menuState.pin);
        setMenuState((s) => ({ ...s, visible: false }));
        update_gpio_MFPs(menuState.key - 1, menuState.pin);
        if (menuKey === '__reset__') {
            result[menuState.key - 1] = "";
        }
        else if (g_disabledSubNodesArray.includes(`${menuKey}_Intermediate`)) {
            const intermediateKey = r_pinCurrentDescription.indexOf(menuKey);
            if (intermediateKey !== -1) {
                result[intermediateKey] = "";
                update_gpio_MFPs(intermediateKey, NUTOOL_PIN.g_cfg_pkgs[NUTOOL_PIN.g_packageNumberIndex][intermediateKey]);
            }
            result[menuState.key - 1] = menuKey
            update_gpio_MFPs(menuState.key - 1, menuKey, true);
        }
        else {
            result[menuState.key - 1] =  menuKey;
            update_gpio_MFPs(menuState.key - 1, menuKey, true);
        }
        dispatch(setMfpRegisterName(Object.assign([], g_gpio_MFPs)));
        dispatch(setPinCurrentDescription(result));
    };

    if (!menuState.visible) return null;

    const pinDescription = menuState.PinDescriptions[menuState.key - 1];
    const pinCurrent = r_pinCurrentDescription[menuState.key - 1];

    const menuItems = [
        ...String(pinDescription).split('/').map((pin) => {
            const trimmed = pin.trim();
            const desc = getGpioDescription(trimmed);
            return {
                key: trimmed,
                label: desc
                    ? <Tooltip title={desc} placement="right" color="#ffffe1" overlayInnerStyle={{ color: 'black' }}>{trimmed}</Tooltip>
                    : trimmed,
            };
        }),
        { key: '__reset__', label: 'Reset' },
    ];

    return (
        <>
            <div
                style={{ position: 'fixed', inset: 0, zIndex: 999 }}
                onClick={() => setMenuState((s) => ({ ...s, visible: false }))}
            />
            <div style={{ position: 'fixed', left: menuState.x, top: menuState.y, zIndex: 1000 }}>
                <ConfigProvider theme={{ components: { Menu: {
                    itemSelectedBg: g_colorForConfiguredByUser,
                    itemSelectedColor: '#000',
                    itemHeight: 24,
                }}}}>
                    <Menu
                        items={menuItems}
                        selectedKeys={[pinCurrent]}
                        onClick={handleMenuClick}
                        style={{ boxShadow: '4px 6px 16px rgba(0,0,0,0.55)', borderRadius: 4, minWidth: MENU_WIDTH, fontSize: 12 }}
                    />
                </ConfigProvider>
            </div>
        </>
    );
};

export default PinContextMenu;
